import {
	Component,
	Element,
	Event,
	EventEmitter,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { generateShortID } from "../../utils/function-helper";
import { hasSlot } from "../../utils/slot";

/**
 * @since 1.0.0
 * @status stable
 *
 * @slot - The radio button's label.
 * @slot prefix - A presentational prefix icon or similar element.
 * @slot suffix - A presentational suffix icon or similar element.
 *
 * @part base - The component's base wrapper.
 * @part text - The component's base wrapper for the text button.
 * @part error - The component's base wrapper with the error state.
 * @part prefix - The prefix container.
 * @part label - The button's label.
 * @part suffix - The suffix container.
 * @part caret - The button's caret.
 */

@Component({
	tag: "hbr-radio-button",
	styleUrl: "radio-button.scss",
	shadow: true,
})
export class RadioButton {
	input: HTMLButtonElement;
	hiddenInput: HTMLButtonElement;

	@Element() host: HTMLHbrRadioButtonElement;

	@State() protected hasFocus = false;
	@State() private hasLabel = false;
	@State() private hasPrefix = false;
	@State() private hasSuffix = false;
	@State() tooltipId = `tooltip-${generateShortID()}`;

	/**
	 * @internal The radio button's checked state. This is exposed as an "internal" attribute so we can reflect it, making
	 * it easier to style in button groups.
	 */
	@Prop({ mutable: true, reflect: true }) checked = false;

	/** The radio's value. When selected, the radio group will receive this value. */
	@Prop() value: string;

	/** Disables the radio button. */
	@Prop({ reflect: true }) disabled = false;

	/** The radio button's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Draws a pill-style radio button with rounded edges. */
	@Prop({ reflect: true }) pill = false;

	/** Tooltip content if the icon button serves as a tooltip reference. */
	@Prop({ reflect: true }) tooltip: string;

	/** Attributes related to screen readers. */
	@Prop() aria: { label?: string } = {};

	connectedCallback() {
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleClick = this.handleClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.host.setAttribute("role", "presentation");
	}
	componentDidLoad() {
		this.hiddenInput = this.host.querySelector(".hidden-input");
	}

	private handleSlotChange() {
		this.hasLabel = hasSlot(this.host);
		this.hasPrefix = hasSlot(this.host, "prefix");
		this.hasSuffix = hasSlot(this.host, "suffix");
	}

	/** Emitted when the button loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	/** Emitted when the button gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	private handleFocus() {
		this.hasFocus = true;
		this.hbrFocus.emit();
	}

	private handleBlur() {
		this.hasFocus = false;
		this.hbrBlur.emit();
	}

	private handleClick(event: MouseEvent) {
		if (this.disabled) {
			event.preventDefault();
			event.stopPropagation();
			return;
		}

		this.checked = true;
	}

	@Watch("disabled")
	handleDisabledChange() {
		this.host.setAttribute("aria-disabled", this.disabled ? "true" : "false");
	}

	/** Sets focus on the radio button. */
	focus(options?: FocusOptions) {
		this.input.focus(options);
	}

	/** Removes focus from the radio button. */
	blur() {
		this.input.blur();
	}

	render() {
		return (
			<div part="base" role="presentation">
				<button
					part={`button${this.checked ? " button--checked" : ""}`}
					ref={(el) => {
						this.input = el;
					}}
					role="radio"
					aria-checked={this.checked.toString()}
					aria-label={this.aria?.label}
					class={{
						button: true,
						"button--default": true,
						"button--small": this.size === "small",
						"button--medium": this.size === "medium",
						"button--large": this.size === "large",
						"button--checked": this.checked,
						"button--disabled": this.disabled,
						"button--focused": this.hasFocus,
						"button--outline": true,
						"button--pill": this.pill,
						"button--has-label": this.hasLabel,
						"button--has-prefix": this.hasPrefix,
						"button--has-suffix": this.hasSuffix,
					}}
					aria-disabled={this.disabled.toString()}
					aria-describedby={this.tooltip ? this.tooltipId : null}
					type="button"
					value={this.value}
					tabindex={this.checked ? "0" : "-1"}
					onBlur={this.handleBlur}
					onFocus={this.handleFocus}
					onClick={this.handleClick}
				>
					<span part="prefix" class="button__prefix">
						<slot name="prefix" onSlotchange={this.handleSlotChange} />
					</span>
					<span part="label" class="button__label">
						<slot onSlotchange={this.handleSlotChange} />
					</span>
					<span part="suffix" class="button__suffix">
						<slot name="suffix" onSlotchange={this.handleSlotChange} />
					</span>
				</button>
				<span id={this.tooltipId} hidden>
					{this.tooltip}
				</span>
			</div>
		);
	}
}
